import React from 'react';
import { useHistory } from 'react-router-dom';
import './MainPage.css'; // Make sure to create this CSS file with styles

const MainPage = () => {
  const history = useHistory();

  const navigateToProfile = () => {
    history.push('/ProfilePage'); // Adjust the path according to your routing setup
  };

  return (
    <div className="main-page">
      <div className="header">
        <img src="image1.jpg" alt="Logo" className="logo" />
      </div>
      <div className="search-section">
        <input type="text" placeholder="Search..." className="search-input" />
        <button className="profile-button" onClick={navigateToProfile}>
          Profile
        </button>
      </div>
    </div>
  );
};

export default MainPage;
